package main

import (
	"crypto/subtle"
	"encoding/base64"
	"net/http"
	"strconv"
)

// AuthUserKey is the key holding the authenticated user name.
const AuthUserKey = "user"

// AuthProxyUserKey is the key holding the authenticated proxy user name.
const AuthProxyUserKey = "proxy_user"

// Accounts defines a key/value for user/pass list of authorized logins.
type Accounts map[string]string

// AuthPair is one compiled entry of the credential table.
type AuthPair struct {
	Value string
	User  string
}

// AuthPairs is the reusable credential table built from Accounts.
type AuthPairs []AuthPair

// AuthResult is the outcome of checking one header value.
type AuthResult struct {
	Authorized  bool
	User        string
	Status      int
	HeaderName  string
	HeaderValue string
}

// AuthorizationHeader returns the credential value for user/password.
func AuthorizationHeader(user, password string) string {
	base := user + ":" + password
	return "Basic " + base64.RawStdEncoding.EncodeToString([]byte(base))
}

// SearchCredential looks up a header value by exact whole-string equality.
func (a AuthPairs) SearchCredential(authValue string) (string, bool) {
	if authValue == "" {
		return "", false
	}
	for _, pair := range a {
		if subtle.ConstantTimeCompare([]byte(pair.Value), []byte(authValue)) == 1 {
			return pair.User, true
		}
	}
	return "", false
}

// ProcessAccounts compiles an account table into a credential table.
func ProcessAccounts(accounts Accounts) AuthPairs {
	length := len(accounts)
	if length > 0 == false {
		panic("Empty list of authorized credentials")
	}
	pairs := make(AuthPairs, 0, length)
	for user, password := range accounts {
		if user == "" {
			panic("User can not be empty")
		}
		pairs = append(pairs, AuthPair{
			Value: AuthorizationHeader(user, password),
			User:  user,
		})
	}
	return pairs
}

func challenge(realm string) string {
	return "Basic realm=" + strconv.Quote(realm)
}

// BasicAuthForRealm returns a checker over the Authorization header value.
func BasicAuthForRealm(accounts Accounts, realm string) func(headerValue string) AuthResult {
	if realm == "" {
		realm = "Authorization Required"
	}
	authHeader := challenge(realm)
	pairs := ProcessAccounts(accounts)
	return func(headerValue string) AuthResult {
		user, found := pairs.SearchCredential(headerValue)
		if !found {
			return AuthResult{Status: http.StatusUnauthorized, HeaderName: "WWW-Authenticate", HeaderValue: authHeader}
		}
		return AuthResult{Authorized: true, User: user, Status: http.StatusOK}
	}
}

// BasicAuth returns a checker using the default realm.
func BasicAuth(accounts Accounts) func(headerValue string) AuthResult {
	return BasicAuthForRealm(accounts, "")
}

// BasicAuthForProxy returns a checker over the Proxy-Authorization header value.
func BasicAuthForProxy(accounts Accounts, realm string) func(headerValue string) AuthResult {
	if realm == "" {
		realm = "Proxy Authorization Required"
	}
	authHeader := challenge(realm)
	pairs := ProcessAccounts(accounts)
	return func(headerValue string) AuthResult {
		user, found := pairs.SearchCredential(headerValue)
		if !found {
			return AuthResult{Status: http.StatusProxyAuthRequired, HeaderName: "Proxy-Authenticate", HeaderValue: authHeader}
		}
		return AuthResult{Authorized: true, User: user, Status: http.StatusOK}
	}
}

