package main

import (
    "fmt"
    "os"
    "strings"
)

var tPass, tFail int

func tOk(name string, cond bool) {
    if cond {
        tPass++
    } else {
        tFail++
        fmt.Fprintln(os.Stderr, name)
    }
}

func tPanic(name string, accounts Accounts, want string) {
    defer func() {
        r := recover()
        if r == nil {
            tFail++
            fmt.Fprintln(os.Stderr, name, "no panic")
            return
        }
        if strings.Contains(fmt.Sprintf("%v", r), want) {
            tPass++
        } else {
            tFail++
            fmt.Fprintln(os.Stderr, name, r)
        }
    }()
    ProcessAccounts(accounts)
}

func main() {
    tOk("padding", AuthorizationHeader("a", "") == "Basic YTo=")
    tOk("no padding", AuthorizationHeader("u", "p") == "Basic dTpw")
    tOk("standard", AuthorizationHeader("user", "pass") == "Basic dXNlcjpwYXNz")

    p := ProcessAccounts(Accounts{"a": ""})
    tOk("single len", len(p) == 1)
    if len(p) == 1 {
        tOk("single value", p[0].Value == "Basic YTo=")
        tOk("single user", p[0].User == "a")
        u, found := p.SearchCredential("Basic YTo=")
        tOk("hit", found && u == "a")
        u, found = p.SearchCredential("Basic YTo")
        tOk("prefix miss", !found && u == "")
        u, found = p.SearchCredential(" basic YTo=")
        tOk("space miss", !found && u == "")
        u, found = p.SearchCredential("basic YTo=")
        tOk("case miss", !found && u == "")
        u, found = p.SearchCredential("Token YTo=")
        tOk("scheme miss", !found && u == "")
        u, found = p.SearchCredential("")
        tOk("empty miss", !found && u == "")
    }

    q := ProcessAccounts(Accounts{"alice": "secret", "bob": "pw"})
    tOk("multi len", len(q) == 2)
    for _, pair := range q {
        u, found := q.SearchCredential(pair.Value)
        tOk("multi hit "+pair.User, found && u == pair.User)
    }
    u, found := q.SearchCredential("Basic unknown")
    tOk("unknown miss", !found && u == "")

    tPanic("empty accounts", Accounts{}, "Empty list of authorized credentials")
    tPanic("empty user", Accounts{"": "x"}, "User can not be empty")

    fmt.Printf("TESTS %d %d\n", tPass, tFail)
    if tFail > 0 {
        os.Exit(1)
    }
}
